<template>
  <sravx-page-back root-only />
<view class="page"><view v-for="item in fields" :key="item.key" class="group"><text>{{item.label}}<text class="ui-b" v-if="item.required">*</text></text><input v-if="item.type==='input'" v-model="form[item.key]" :type="item.inputType||'text'" :maxlength="item.max||200" :placeholder="item.placeholder"/><picker v-else-if="item.type==='picker'" :range="item.options" :value="indexOf(item)" @change="pick(item,$event)"><view :class="form[item.key]?'filled':'placeholder'">{{form[item.key]||item.placeholder}}　⌄</view></picker><textarea v-else v-model="form[item.key]" maxlength="500" :placeholder="item.placeholder" auto-height/></view><view class="actions"><button :class="{disabled:submitting}" @tap="submit">{{submitting?'提交中...':'提交咨询'}}</button><button open-type="contact" session-from="cooperation">在线客服</button></view><view v-if="confirming" class="mask" @tap="confirming=false"><view class="modal" @tap.stop><text class="ui-strong">请确认合作信息</text><scroll-view scroll-y><view v-for="item in fields.filter(x=>form[x.key])" :key="item.key"><text>{{item.label}}</text><text>{{form[item.key]}}</text></view></scroll-view><view><button @tap="confirming=false">返回修改</button><button class="primary" @tap="confirm">{{submitting?'提交中...':'确认提交'}}</button></view></view></view></view></template>
<script>
import SravxPageBack from '../../components/sravx-page-back/sravx-page-back.vue'
import api from '../../common/api.js';export default{components:{SravxPageBack},data(){return{form:{name:'',gender:'',scale:'',phone:'',wechat:'',address:'',intention:''},submitting:false,confirming:false,fields:[{key:'name',label:'称呼',required:true,type:'input',placeholder:'请输入您的称呼',max:20},{key:'gender',label:'性别',required:true,type:'picker',options:['男','女'],placeholder:'请选择性别'},{key:'scale',label:'规模',required:true,type:'picker',options:['个人','学校','门店','企业'],placeholder:'请选择规模'},{key:'phone',label:'联系号码',required:true,type:'input',inputType:'number',placeholder:'请输入手机号码',max:11},{key:'wechat',label:'微信号码',type:'input',placeholder:'请输入微信号码（选填）',max:30},{key:'address',label:'联系地址',type:'input',placeholder:'请输入联系地址（选填）'},{key:'intention',label:'合作意向',type:'textarea',placeholder:'请描述您的合作意向或需求...'}]}},methods:{indexOf(item){return Math.max(0,item.options.indexOf(this.form[item.key]))},pick(item,event){this.form[item.key]=item.options[Number(event.detail.value)]||''},valid(){const x=this.form;if(!x.name.trim())return'请填写称呼';if(!x.gender)return'请选择性别';if(!x.scale)return'请选择规模';if(!x.phone.trim())return'请填写联系号码';if(!/^1\d{10}$/.test(x.phone.trim()))return'联系号码格式不正确';return''},submit(){const error=this.valid();if(error)return uni.showToast({title:error,icon:'none'});this.confirming=true},async confirm(){if(this.submitting)return;this.submitting=true;try{await api.submitCooperation(this.form);this.confirming=false;uni.showToast({title:'提交成功，我们将尽快联系您',icon:'success'});setTimeout(()=>uni.navigateBack(),1500)}catch(error){uni.showToast({title:error.message||'提交失败，请重试',icon:'none'})}finally{this.submitting=false}}}}</script>
<style>.page{min-height:100vh;padding:12px 16px 60px;box-sizing:border-box;background:#F4F6F8}.group{padding:14px;margin-bottom:8px;border-radius:10px;background:#fff}.group>text{display:block;margin-bottom:10px;font-size:14px;font-weight:500}.group .ui-b{margin-left:2px;color:#4A4A4D}.group input,.group picker,.group textarea{width:100%;min-height:40px;padding:0 10px;box-sizing:border-box;border-radius:6px;background:#F4F6F8;font-size:13px}.group picker{padding:12px 10px}.placeholder{color:#c7c7cc}.filled{color:#0B0D10}.group textarea{min-height:100px;padding:10px}.actions button{margin-top:10px;border-radius:22px;background:#0B0D10;color:#fff;font-size:15px;line-height:44px}.actions button+button{margin-top:8px;background:#fff;color:#636366}.actions button::after,.modal button::after{border:0}.disabled{opacity:.5}.mask{position:fixed;z-index:10;inset:0;display:flex;align-items:center;justify-content:center;padding:24px;background:rgba(0,0,0,.45)}.modal{width:100%;max-height:75vh;padding:22px;border-radius:14px;background:#fff}.modal>.ui-strong{display:block;margin-bottom:12px;text-align:center;font-size:17px}.modal scroll-view{max-height:50vh}.modal scroll-view view{display:flex;gap:12px;padding:9px 0;border-bottom:1px solid #eee;font-size:13px}.modal scroll-view view text:first-child{width:65px;color:#636366}.modal>view:last-child{display:flex;gap:10px;margin-top:14px}.modal button{flex:1;background:#F4F6F8;font-size:14px;line-height:40px}.modal button.primary{background:#0B0D10;color:#fff}</style>
